def workspace_revision_delta(before: dict[str, str], after: dict[str, str], limit: int = 80) -> list[str]:
    return [
        path for path in sorted(set(before) | set(after))
        if before.get(path) != after.get(path)
    ][:max(1, int(limit or 80))]

